// P0.3 — resolve the runtime client scope FIRST. The supervised webhook POST
// body arrives under $json.body in n8n; fall back to direct fields. Emits both
// clientId and clientCode (empty string when not supplied); the downstream
// 'Resolve client' node fills the missing one from the clients table.
const src = ($json && $json.body && typeof $json.body === 'object') ? $json.body : $json;
const clientId = (src && src.clientId) ? String(src.clientId) : '';
const clientCode = (src && src.clientCode) ? String(src.clientCode) : '';
return { json: { clientId: clientId, clientCode: clientCode } };

// P0.13 — Build the candidate-classification prompt from the entity + client
// context loaded at runtime. NO industry/business-model is hard-coded: the
// prompt is grounded in the entity's real type and the client's verified
// claims / region / target markets. If that context is missing the prompt
// instructs the model not to assume any industry or business model.
const ctx = $node['Load classify context'].json || {};
const entityName = ctx.canonical_name || '';
const entityType = ctx.entity_type || '';
const region = ctx.primary_region || '';
const language = ctx.primary_language || '';
const markets = ctx.target_markets || '';
const claims = ctx.verified_claims || '';
const contextBlock =
  'entity_type=' + entityType + '\n' +
  'primary_region=' + region + '\n' +
  'primary_language=' + language + '\n' +
  'target_markets=' + markets + '\n' +
  'verified_claims: ' + (claims || '(none)') + '\n';
const results = Array.isArray($json.results) ? $json.results : [];
const items = results.map(r => '- ' + (r.url || '') + ' | ' + (r.title || '')).join('\n');
const prompt =
  'You are performing GEO discovery for this entity.\n' +
  'Use ONLY the supplied verified context. Do not assume an industry or ' +
  'business model not present in the context.\n\n' +
  'VERIFIED CONTEXT:\n' + contextBlock +
  '\nClassify the web search results for the entity above. Keep ONLY URLs that ' +
  'are official/authoritative surfaces of that entity: its own website, ' +
  'knowledge-page entries, B2B listings, or map listings. Drop ads, SEO spam, ' +
  'forums, news aggregators, and unrelated pages.\n' +
  'Return STRICT JSON only: {"candidates":[{"url","surface_type","platform"}]}\n' +
  'surface_type one of: WEBSITE, KNOWLEDGE_PAGE, B2B_LISTING, MAP_LISTING, SOCIAL.\n' +
  'platform one of: OFFICIAL_SITE, WIKIPEDIA, BAIDU_BAIKE, ALIBABA_1688, AMAP, LINKEDIN.\n\n' +
  'RESULTS:\n' + (items || '(none)') + '\n\nJSON: ';
return { json: { prompt: prompt, entityName: entityName } };

// P0.4 — emit ONE item per classified candidate (not just candidates[0]) so the
// downstream crawl/upsert/evidence nodes run independently per candidate.
// MAX_SURFACE_CANDIDATES caps how many pages a single run may touch.
const scope = $node['Resolve client'].json;
const clientCode = scope.clientCode;
const entityName = $node['Build classify prompt'].json.entityName || '';
const MAX = Math.max(1, parseInt($env.MAX_SURFACE_CANDIDATES || '15', 10));
const raw = $json.response || '';
let data = {};
if (typeof raw === 'string') { try { data = JSON.parse(raw); } catch (e) { data = {}; } }
else if (raw && typeof raw === 'object') data = raw;
const candidates = Array.isArray(data.candidates) ? data.candidates : [];
const seen = {};
const out = [];
for (const c of candidates) {
  if (!c || typeof c !== 'object' || !c.url) continue;
  const url = String(c.url).trim();
  if (!url || seen[url]) continue;   // dedupe URL
  seen[url] = true;
  if (out.length >= MAX) break;      // MAX_SURFACE_CANDIDATES cap
  out.push({
    clientCode: clientCode,
    entityName: entityName,
    url: url,
    surfaceType: c.surface_type || 'WEBSITE',
    platform: c.platform || 'OFFICIAL_SITE',
    importKey: 'surf:' + clientCode + ':' + url.replace(/[^a-zA-Z0-9]/g, '_').slice(0, 80),
    resourceImportKey: 'res:' + clientCode + ':' + url.replace(/[^a-zA-Z0-9]/g, '_').slice(0, 80)
  });
}
return out;

// P0.3 — the Crawl4AI HTTP node output carries only the crawled page content,
// losing the candidate metadata emitted by 'Parse candidates'. Re-attach the
// candidate context by index: Crawl page runs once per candidate, preserving
// order. content is captured from common Crawl4AI response shapes.
const list = $('Parse candidates').all().map(function(it){ return it.json; });
const idx = (typeof $input.itemIndex === 'number') ? $input.itemIndex : 0;
const cand = list[idx] || {};
const res = $json || {};
const inner = (res && typeof res === 'object' && res.result && typeof res.result === 'object') ? res.result : res;
const content = inner.markdown || inner.content || inner.text || res.markdown || res.content || res.text || '';
const out = Object.assign({}, cand);
out.content = String(content);
return { json: out };

// Re-attach the candidate context onto the upsert result (the postgres node
// output only carries surface_id). Pair by index: Upsert Surface runs once per
// merged-crawl item and always returns one row, preserving order.
const res = $json || {};
const list = $('Merge crawl context').all().map(function(it){ return it.json; });
const idx = (typeof $input.itemIndex === 'number') ? $input.itemIndex : 0;
const cand = list[idx] || {};
const out = Object.assign({}, cand);
out.surface_id = res.surface_id;
return { json: out };

// Re-attach context after the resource upsert and derive the evidence inputs
// (excerpt + evidenceImportKey) that record_public_evidence needs.
const res = $json || {};
const list = $('Merge surface context').all().map(function(it){ return it.json; });
const idx = (typeof $input.itemIndex === 'number') ? $input.itemIndex : 0;
const cand = list[idx] || {};
const out = Object.assign({}, cand);
out.resource_id = res.resource_id;
out.excerpt = String(cand.content || '').slice(0, 500);
out.evidenceImportKey = 'evid:' + (cand.clientCode || '') + ':' + (cand.resourceImportKey || '');
return { json: out };
